messages.content:
Tool response:
Tool: create_bulk_lot
Description: Create Bulk Lot
Parameters:
    {
      "type": "object",
      "properties": {
        "seller_id": {
          "type": "integer",
          "title": "Seller Id"
        },
        "marketplace_id": {
          "type": "integer",
          "title": "Marketplace Id"
        },
        "condition_id": {
          "type": "integer",
          "title": "Condition Id"
        },
        "title": {
          "type": "string",
          "title": "Title"
        },
        "total_retail_value": {
          "type": "number",
          "title": "Total Retail Value"
        },
        "starting_bid": {
          "type": "number",
          "title": "Starting Bid"
        },
        "reserve_price": {
          "anyOf": [
            {
              "type": "number"
            },
            {
              "type": "null"
            }
          ],
          "title": "Reserve Price"
        },
        "bid_increment": {
          "type": "number",
          "title": "Bid Increment"
        },
        "auction_start": {
          "type": "string",
          "title": "Auction Start"
        },
        "auction_end": {
          "type": "string",
          "title": "Auction End"
        },
        "shipping_cost": {
          "type": "number",
          "title": "Shipping Cost"
        },
        "shipping_method": {
          "type": "string",
          "title": "Shipping Method"
        },
        "local_pickup_location": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "title": "Local Pickup Location"
        },
        "manifest_items": {
          "items": {
            "properties": {
              "sku": {
                "type": "string",
                "title": "Sku"
              },
              "quantity": {
                "type": "integer",
                "title": "Quantity"
              },
              "unit_retail_price": {
                "type": "number",
                "title": "Unit Retail Price"
              }
            },
            "type": "object",
            "required": [
              "sku",
              "quantity",
              "unit_retail_price"
            ],
            "title": "ManifestItemRequest"
          },
          "type": "array",
          "title": "Manifest Items"
        }
      },
      "required": [
        "seller_id",
        "marketplace_id",
        "condition_id",
        "title",
        "total_retail_value",
        "starting_bid",
        "bid_increment",
        "auction_start",
        "auction_end",
        "shipping_cost",
        "shipping_method",
        "manifest_items"
      ]
    }
